import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.sqrt

fun countSuitable(x: Long): Long {
    var cnt = 0L
    val limit = sqrt(x.toDouble()).toLong()
    for (a in 1L..limit) {
        val t = x / a
        if (t <= a) continue
        val bMin = a + 1
        val bMax = t - 1
        if (bMax >= bMin) {
            cnt += bMax - bMin + 1
        }
    }
    return cnt
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val N = br.readLine().trim().toLong()

    var low = 1L
    var high = 2_000_000_000_000_000_000L  // large upper bound

    while (low < high) {
        val mid = (low + high) ushr 1
        if (countSuitable(mid) >= N) high = mid else low = mid + 1
    }

    println(low)
}

