    val N = br.readLine().trim().toLong()

    fun countSuitable(x: Long): Long {
        var cnt = 0L
        val limit = (sqrt((4.0 * x + 1).toDouble()) - 1).toLong()
        var a = 1L
        while (a <= limit) {
            val numerator = 4 * x - a * a
            val denominator = 2 * a
            if (numerator > 0 && numerator % denominator == 0L) {
                val b = numerator / denominator
                if (b > a) cnt++
            }
            a++
        }
        return cnt
    }

    var low = 1L
    var high = 4_000_000_000_000_000_000L
    while (low < high) {
        val mid = (low + high) ushr 1
        if (countSuitable(mid) >= N) high = mid else low = mid + 1
    }
    println(low)
}

