import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.sqrt

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val N = br.readLine().trim().toLong()

    fun count(x: Long): Long {
        var res = 0L
        val limitA = (sqrt((x / 2.0))).toLong()
        var a = 1L
        while (a <= limitA) {
            val maxB = x / a - a
            if (maxB > a) {
                res += maxB - a
            }
            a++
        }
        return res
    }

    var low = 1L
    var high = 2_000_000_000L
    while (low < high) {
        val mid = (low + high) ushr 1
        if (count(mid) >= N) high = mid else low = mid + 1
    }
    println(low)
}
